<?php
declare(strict_types=1);
require dirname(__DIR__).'/backend/bootstrap.php';
$config=require dirname(__DIR__).'/backend/config/application.php';
if(!preg_match('/^academia_test_[a-f0-9]{16}$/D',$config['db_name']))throw new RuntimeException('Usa tests/isolated.php personnel-import.php.');
$db=new Academia\Support\Database($config);
$site=(int)$db->run('SELECT id FROM sites ORDER BY id LIMIT 1')->fetchColumn();
$directory=dirname($config['storage']);
$repo=new Academia\Repositories\PersonnelRepository($db);
$tool=new Academia\Services\PersonnelImportTool($repo,$config);
$checks=0;
function verify(bool $condition,string $message):void{global $checks;$checks++;if(!$condition)throw new RuntimeException($message);}
function rejects(callable $task,int $status,string $message):void{try{$task();}catch(Academia\Http\ApiException $error){verify($error->getCode()===$status,$message.' status');return;}throw new RuntimeException($message);}
function person(string $dni):array{global $repo;foreach($repo->list() as $row)if($row['dni']===$dni)return $row;throw new RuntimeException('Missing synthetic person');}
$csv=$directory.'/personal.csv';
$db->pdo->beginTransaction();
try{
    file_put_contents($csv,"DNI,NOMBRE COMPLETO,CARGO\n12345670,Persona Uno,Operaciones\n12345671,Persona Dos,Administración\n");
    $result=$tool->importFile($csv,$site);
    if($result['created']!==2)throw new RuntimeException('CSV: expected 2 synthetic rows');
    file_put_contents($csv,"DNI,NOMBRE COMPLETO,CARGO\n1234AB5678,Persona Inválida,Prueba\n");
    try{$tool->importFile($csv,$site);throw new RuntimeException('Malformed DNI accepted');}catch(Academia\Http\ApiException $e){if($e->getCode()!==422)throw $e;}
    file_put_contents($csv,"DNI,NOMBRE COMPLETO,CARGO\n12345672,Persona Multilínea,\"Cargo\nmultilínea\"\n");
    if($tool->importFile($csv,$site)['created']!==1)throw new RuntimeException('Quoted multiline CSV failed');
    $xlsx=$directory.'/sintetico.xlsx';
    file_put_contents($xlsx,Academia\Support\XlsxWriter::build([['DNI','NOMBRE COMPLETO','CARGO'],['12345673','Persona Excel','Prueba']],1));
    if($tool->importFile($xlsx,$site)['created']!==1)throw new RuntimeException('Synthetic XLSX failed');
    $db->run("INSERT INTO sites(name,address) VALUES('Breña Norte','')");$north=(int)$db->pdo->lastInsertId();
    $db->run("INSERT INTO sites(name,address,active) VALUES('Sede Inactiva','',0)");$inactive=(int)$db->pdo->lastInsertId();
    $worker=['dni'=>'00123456','name'=>'Trabajador Individual','job_title'=>'Operaciones','site_id'=>$site,'active'=>1];
    $repo->save($worker);verify(person('00123456')['dni']==='00123456','DNI preserves leading zeros');
    rejects(fn()=>$repo->save($worker),409,'Create never updates existing record');
    foreach([['dni'=>'1234567x'],['dni'=>12345678],['name'=>'ab'],['job_title'=>''],['site_id'=>$inactive],['site_id'=>999999],['active'=>2]] as $invalid)rejects(fn()=>$repo->save(array_replace($worker,['dni'=>'00123457'],$invalid)),422,'Invalid individual input rejected');
    $edit=person('00123456');$repo->save(array_replace($edit,['name'=>'Nombre Corregido','site_id'=>$north]),true);
    verify((int)person('00123456')['site_id']===$north,'Individual reassignment');
    verify(person('12345670')['name']==='Persona Uno','Individual save leaves unrelated person intact');
    rejects(fn()=>$repo->save(array_replace($edit,['job_title'=>'Obsoleto']),true),409,'Stale edit rejected');
    rejects(fn()=>$repo->remove($edit),409,'Stale deletion rejected');
    rejects(fn()=>$repo->save(array_replace($edit,['dni'=>'00999999']),true),404,'Update never creates');
    $db->run("INSERT INTO courses(title,category,description) VALUES('Prueba personal','Pruebas','Prueba')");$course=(int)$db->pdo->lastInsertId();
    $db->run("INSERT INTO exams(course_id,version,questions_json) VALUES(?,1,'[]')",[$course]);$exam=(int)$db->pdo->lastInsertId();
    $db->run("INSERT INTO enrollments(exam_id,dni,name,job_title,phone,area) VALUES(?,'00123456','Nombre Corregido','Operaciones','','')",[$exam]);$enrollment=(int)$db->pdo->lastInsertId();
    $db->run("INSERT INTO attempts(enrollment_id,token_hash,status,score) VALUES(?,?,'completed',20)",[$enrollment,str_repeat('a',64)]);
    $repo->remove(person('00123456'));verify(!(int)person('00123456')['active'],'Logical deletion');
    verify((int)$db->run('SELECT score FROM attempts WHERE enrollment_id=?',[$enrollment])->fetchColumn()===20,'Examination history preserved');
    rejects(fn()=>$repo->findActive('00123456'),404,'Inactive person cannot participate');
    rejects(fn()=>$repo->save($worker),409,'Inactive DNI cannot be recreated');
    $repo->save(array_replace(person('00123456'),['active'=>1]),true);verify((int)person('00123456')['active']===1,'Explicit reactivation');
    $db->run("INSERT INTO admins(name,dni,job_title,email,password_hash,role,site_id) VALUES('Nombre Corregido','00123456','Operaciones','personnel@example.invalid','synthetic','capacitador',?)",[$north]);$account=(int)$db->pdo->lastInsertId();
    $auth=new Academia\Services\AuthTool($db,$config);$_SESSION['admin']=['id'=>$account,'auth_version'=>0];
    verify($auth->user(true)!==null,'Linked trainer session starts active');
    $repo->save(array_replace(person('00123456'),['site_id'=>$site]),true);
    verify((int)$db->run('SELECT site_id FROM admins WHERE id=?',[$account])->fetchColumn()===$site,'Individual site change synchronizes linked access');
    verify($auth->user(true)===null,'Site change revokes previous trainer session');
    $repo->save(array_replace(person('00123456'),['site_id'=>$north]),true);
    $version=(int)$db->run('SELECT auth_version FROM admins WHERE id=?',[$account])->fetchColumn();
    $_SESSION['admin']=['id'=>$account,'auth_version'=>$version];verify($auth->user(true)!==null,'Trainer can sign in to reassigned site');
    $repo->remove(person('00123456'));
    verify(!(int)$db->run('SELECT active FROM admins WHERE id=?',[$account])->fetchColumn(),'Deleting worker disables linked access');
    verify($auth->user(true)===null,'Deleting worker revokes active session');
    $repo->save(array_replace(person('00123456'),['active'=>1]),true);
    verify(!(int)$db->run('SELECT active FROM admins WHERE id=?',[$account])->fetchColumn(),'Reactivation does not restore administrative access implicitly');
    $db->run('UPDATE admins SET active=1 WHERE id=?',[$account]);
    $repo->save(array_replace(person('00123456'),['active'=>0,'name'=>'Corrección Inactiva']),true);
    verify(!(int)$db->run('SELECT active FROM admins WHERE id=?',[$account])->fetchColumn(),'Inactive update also disables linked access');
    verify($db->run('SELECT name FROM enrollments WHERE id=?',[$enrollment])->fetchColumn()==='Corrección Inactiva','Inactive edit synchronizes reports too');
    $repo->save(array_replace(person('00123456'),['active'=>1]),true);
    $repo->save(array_replace(person('00123456'),['name'=>'Nombre Sincronizado','job_title'=>'Supervisor']),true);
    verify($db->run('SELECT name FROM admins WHERE id=?',[$account])->fetchColumn()==='Nombre Sincronizado','Trainer name synchronized');
    verify($db->run('SELECT job_title FROM enrollments WHERE id=?',[$enrollment])->fetchColumn()==='Supervisor','Enrollment data synchronized');
    $db->run('UPDATE admins SET active=1 WHERE id=?',[$account]);
    $rows=[['dni'=>'00123456','name'=>'Nombre Importado','job_title'=>'Supervisor','site'=>'sede  de pruebas'],['dni'=>'00123458','name'=>'Nueva Persona','job_title'=>'Prueba','site'=>'  BRENA   NORTE  ']];
    $preview=$repo->importRows($rows,0,true);
    verify($preview['created']===1&&$preview['updated']===1&&$preview['transfer_count']===1&&$preview['sites']===2,'Preview detects mixed sites and transfer');
    verify($preview['linked_accounts']===1,'Preview includes linked access impact');
    verify((int)person('00123456')['site_id']===$north&&count($repo->list())===5,'Preview makes no writes');
    $repo->importRows($rows,0,false,$preview['preview_token']);
    verify((int)person('00123456')['site_id']===$site&&(int)person('00123458')['site_id']===$north,'File site overrides fallback and accents/spaces normalized');
    verify((int)$db->run('SELECT site_id FROM admins WHERE id=?',[$account])->fetchColumn()===$site,'Mass transfer uses same access synchronization');
    $preview=$repo->importRows($rows,0,true);$db->run('UPDATE admins SET active=0 WHERE id=?',[$account]);
    rejects(fn()=>$repo->importRows($rows,0,false,$preview['preview_token']),409,'Changed linked access requires review again');
    $preview=$repo->importRows($rows,0,true);$repo->importRows($rows,0,false,$preview['preview_token']);
    verify(!(int)$db->run('SELECT active FROM admins WHERE id=?',[$account])->fetchColumn(),'Mass import never revives disabled access');
    $withoutSite=[['dni'=>'00123459','name'=>'Sin Sede','job_title'=>'Prueba']];
    rejects(fn()=>$repo->importRows($withoutSite,0,true),422,'No automatic default site');
    $default=$repo->importRows($withoutSite,$north,true);verify($default['defaulted']===1&&$default['site_totals'][0]['name']==='Breña Norte','Explicit fallback visible');
    foreach(['No Existe','Sede Inactiva'] as $badSite){$invalid=[...$withoutSite,['dni'=>'00123460','name'=>'Sede Inválida','job_title'=>'Prueba','site'=>$badSite]];rejects(fn()=>$repo->importRows($invalid,$site),422,'Invalid site rejects full batch');}
    verify(!$db->run("SELECT dni FROM employees WHERE dni='00123459'")->fetchColumn(),'No partial import');
    rejects(fn()=>$repo->importRows([...$rows,$rows[0]],0,true),422,'Duplicate DNI in file rejected');
    $preview=$repo->importRows($rows,0,true);
    $repo->save(array_replace(person('00123456'),['job_title'=>'Cambio Individual']),true);
    rejects(fn()=>$repo->importRows($rows,0,false,$preview['preview_token']),409,'Import cannot overwrite individual change after review');
    verify(person('00123456')['job_title']==='Cambio Individual','Individual change survives stale mass import');
    $preview=$repo->importRows($rows,0,true);$changed=$rows;$changed[0]['site']='Breña Norte';
    rejects(fn()=>$repo->importRows($changed,0,false,$preview['preview_token']),409,'Changed file invalidates preview');
    $repo->remove(person('00123458'));$preview=$repo->importRows($rows,0,true);verify($preview['reactivated']===1,'Preview shows reactivation');
    $db->run("UPDATE sites SET name='Breña Central' WHERE id=?",[$north]);
    rejects(fn()=>$repo->importRows($rows,0,false,$preview['preview_token']),422,'Renamed file site rejected');
    file_put_contents($csv,"DNI,NOMBRE COMPLETO,CARGO,SEDE\n00123461,Prueba CSV Sede,Prueba,BRENA CENTRAL\n");
    $preview=$tool->importFile($csv,0,true);verify($preview['site_totals'][0]['name']==='Breña Central','CSV preview validates file site');
    $tool->importFile($csv,0,false,$preview['preview_token']);verify((int)person('00123461')['site_id']===$north,'CSV confirmation persists reviewed site');
    $db->run("UPDATE courses SET site_id=?,status='published' WHERE id=?",[$site,$course]);
    $question=[['prompt'=>'Pregunta de prueba','choices'=>['Sí','No','Otro'],'correct'=>0,'explanation'=>'']];
    $rules=new Academia\Services\ExamRules();$examRepo=new Academia\Repositories\ExamRepository($db,$rules);
    $exam=(int)$examRepo->save($course,['questions'=>$question,'opens_at'=>date('Y-m-d H:i:s',time()-60),'duration_minutes'=>10,'max_attempts'=>2,'passing_score'=>14])['id'];
    $attempts=new Academia\Services\AttemptTool($db,$examRepo,$repo,$rules,2);
    $pending=$attempts->start($course,['dni'=>'00123456']);
    $repo->remove(person('00123456'));
    rejects(fn()=>$attempts->submit(['token'=>$pending['token'],'answers'=>[0]]),404,'Deleted worker cannot submit pending evaluation');
    $repo->save(array_replace(person('00123456'),['active'=>1,'site_id'=>$north]),true);
    rejects(fn()=>$attempts->submit(['token'=>$pending['token'],'answers'=>[0]]),403,'Transferred worker cannot submit evaluation from old site');
    verify((int)$db->run('SELECT site_id FROM courses WHERE id=?',[$course])->fetchColumn()===$site,'Transfer preserves historical course site');
    $repo->save(array_replace(person('00123456'),['site_id'=>$site]),true);
    verify($attempts->submit(['token'=>$pending['token'],'answers'=>[0]])['score']===20,'Eligible active worker can finish evaluation');
    $repo->save(array_replace(person('00123456'),['active'=>0,'name'=>'Nombre Final','job_title'=>'Cargo Final']),true);
    $report=(new Academia\Repositories\ReportRepository($db))->participants($exam);
    verify($report[0]['name']==='Nombre Final'&&$report[0]['job_title']==='Cargo Final'&&(int)$report[0]['score']===20,'Reports share updated identity and retain grades');
    verify($attempts->submit(['token'=>$pending['token'],'answers'=>[0]])['score']===20,'Completed results remain readable after deletion');
    echo "OK $checks comprobaciones de CRUD individual, sedes, revisión, conflictos e historial; CSV y XLSX sintéticos.\n";
}finally{if($db->pdo->inTransaction())$db->pdo->rollBack();}
